```c
#include <stdio.h>
#include <stdlib.h>

static long long count_leq(const int *a, int n, long long S) {
    if (S < 0) return 0;

    long long sum = 0;
    long long ans = 0;
    int left = 0;

    for (int right = 0; right < n; ++right) {
        sum += a[right];

        while (sum > S) {
            sum -= a[left];
            ++left;
        }

        ans += (long long)(right - left + 1);
    }

    return ans;
}

int main(void) {
    int N, K;

    if (scanf("%d %d", &N, &K) != 2) return 0;

    int *X = (int *)malloc((size_t)N * sizeof(int));
    if (!X) return 0;

    for (int i = 0; i < N; ++i) {
        if (scanf("%d", &X[i]) != 1) {
            free(X);
            return 0;
        }
    }

    long long ans = count_leq(X, N, K) - count_leq(X, N, (long long)K - 1);

    printf("%lld\n", ans);

    free(X);
    return 0;
}
```

